const deck = [['Pokémon',3,'Mega Absol ex'],['Pokémon',2,'Mega Audino ex'],['Pokémon',3,'Ralts'],['Pokémon',2,'Kirlia'],['Pokémon',1,'Gardevoir ex'],['Pokémon',2,'Munkidori'],['Pokémon',1,'Fezandipiti ex'],['Pokémon',1,'Budew'],['Pokémon',1,'Manaphy'],['Allenatori',4,'Iono'],['Allenatori',4,'Arven'],['Allenatori',3,'Professor’s Research'],['Allenatori',2,'Boss’s Orders'],['Allenatori',4,'Rare Candy'],['Allenatori',4,'Ultra Ball'],['Allenatori',4,'Nest Ball'],['Allenatori',2,'Earthen Vessel'],['Allenatori',2,'Night Stretcher'],['Allenatori',1,'Counter Catcher'],['Allenatori',1,'Super Rod'],['Allenatori',1,'Technical Machine: Evolution'],['Allenatori',1,'Unfair Stamp'],['Energie',11,'Psychic Energy']];
const params = new URLSearchParams(location.search);
const concepts = {a:'A · Banco del mazzo',b:'B · Decisioni',c:'C · Preparazione'};
const descriptions = {a:'Il mazzo è il luogo di lavoro. Seleziona una carta e chiedi una variante nel suo contesto.',b:'Le alternative sono oggetti da valutare. Motivazioni, differenze e decisione precedono la conversazione.',c:'Parti dall’avversario. Piano, carte pertinenti e discussione sono nello stesso percorso.'};
const state = {concept:concepts[params.get('concept')]?params.get('concept'):'a',page:'home',selected:'Iono',candidate:false,adopted:false,stale:false,phase:0,opponent:'Hydrapple ex',message:'',result:'',response:false};
const $ = s => document.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn = (text,action,cls='',extra='') => `<button type="button" class="${cls}" data-action="${action}" ${extra}>${text}</button>`;
const quantity = (name,proposal=false) => deck.find(c=>c[2]===name)[1] + ((state.adopted||proposal)?(name==='Iono'?-1:name==='Mega Absol ex'?1:0):0);
const version = () => state.adopted?'v4':'v3';
const title = () => '<span class="brand"><span class="brand-mark">P</span>Pokéguru</span>';
const current = () => `<span class="tag">Principale ${version()} · 60 carte</span>`;
function toolbar(){return `<div class="study"><strong>CONFRONTO DEI PERCORSI UX</strong>${Object.entries(concepts).map(([id,label])=>btn(label,'concept',state.concept===id?'active':'',`data-value="${id}" aria-pressed="${state.concept===id}"`)).join('')}${btn('Ricomincia','reset','plain reset')}${btn('Analisi UX','analysis','plain')}</div><div class="study-note">${descriptions[state.concept]} · Prototipo con dati dimostrativi.</div>`}
function navigation(){return `<nav class="nav" aria-label="Attività del mazzo">${btn('Mazzo','deck',state.page==='deck'||(state.concept==='a'&&state.page==='home')?'active':'')}${btn('Varianti','decisions',state.page==='decisions'||(state.concept==='b'&&state.page==='home')?'active':'')}${btn('Preparazione','prepare',state.page==='prepare'||(state.concept==='c'&&state.page==='home')?'active':'')}</nav>`}
function appbar(){return `<header class="appbar"><div class="row">${title()}<div class="project"><b>Mega Absol / Mega Audino</b><small>Standard occidentale · archivio locale</small></div></div>${navigation()}${btn('Risorse','resources','plain')}</header>`}
function rows(proposal=false){return ['Pokémon','Allenatori','Energie'].map(group=>`<h3 style="margin-top:20px">${group}</h3><div class="compact-deck">${deck.filter(d=>d[0]===group).map(d=>`<div class="deck-line"><b>${quantity(d[2],proposal)}</b><span>${d[2]}</span></div>`).join('')}</div>`).join('')}
function deckCanvas(){return `<div class="page-head"><div class="row between"><div><span class="eyebrow">Il tuo mazzo / spazio di lavoro</span><h1>Lista principale</h1></div>${current()}</div><p>Seleziona una carta per valutarne il ruolo o avviare una variante. La principale cambia solo dopo la tua conferma.</p><div class="row">${btn('Controlli · 2 da verificare','checks')}${btn('Versioni','history','plain')}${btn('Copia lista','export','plain')}</div></div>${['Pokémon','Allenatori','Energie'].map(group=>`<div class="section-head"><h2>${group}</h2><span class="muted small">${deck.filter(d=>d[0]===group).reduce((s,d)=>s+quantity(d[2]),0)} carte</span></div><div class="deck-grid">${deck.filter(d=>d[0]===group).map((d)=>`<button class="deck-tile ${state.selected===d[2]?'selected':''}" data-action="card" data-name="${esc(d[2])}" aria-pressed="${state.selected===d[2]}"><span class="count">×${quantity(d[2])}</span><span class="tile-art" aria-hidden="true">${d[0]==='Pokémon'?'◈':d[0]==='Energie'?'✦':'≡'}</span><b>${d[2]}</b><small>${d[2]==='Iono'?'Selezionata per la variante':d[2]==='Mega Absol ex'?'Almeno 3 · vincolo':'Apri contesto'}</small></button>`).join('')}</div>`).join('')}`}
function assistant(){return `<aside class="context" aria-label="Contesto della carta"><div class="context-title"><span class="eyebrow">Assistente nel contesto</span><h2>${state.candidate?'Variante pronta da valutare':'Cosa vuoi cambiare?'}</h2><span class="small muted">${state.candidate?'Percorso: rendere più disponibile Absol':'Nuovo percorso dalla principale '+version()}</span></div><div class="context-card"><div class="card-symbol">≡</div><div><h3>${esc(state.selected)}</h3><span class="muted">${quantity(state.selected)} copie nella principale</span><br>${btn('Dettaglio e vincoli','card-detail','plain')}</div></div>${state.candidate?`<div class="note"><b>Una copia in più di Absol</b><p>Iono 4 → 3 · Mega Absol ex 3 → 4</p><p>60 carte · base v3 · 2 verifiche aperte</p></div><p>Ipotesi: dare più spazio ad Absol. Compromesso: una copia in meno di Iono. L’effetto competitivo va valutato.</p>${btn('Valuta la variante','compare','primary')}${btn('Continua la discussione','discussion','context-action')}`:`<label for="ask">Domanda o modifica da esplorare</label><textarea id="ask" placeholder="Es. Valutiamo una copia in più di Absol al posto di Iono">${esc(state.message)}</textarea><p class="micro">Contesto: lista ${version()}, carta selezionata e vincoli. ${btn('Vedi dati inviati','evidence','plain')}</p>${btn('Chiedi una variante','ask','primary')}<p class="micro">Il titolo nasce dalla richiesta; potrai rinominarlo dopo.</p>`}<div style="margin-top:30px;border-top:1px solid var(--line);padding-top:20px"><h3>Riprendi un percorso</h3>${btn('Più disponibilità di Absol <span>→</span>','candidate','context-action')}${btn('Apri la preparazione <span>→</span>','prepare','context-action')}</div></aside>`}
function workbench(){return `${appbar()}<nav class="compact-switch" aria-label="Mazzo e assistente">${btn('Lista principale','mobile-list',!state.mobileContext?'active':'')}${btn('Assistente · '+esc(state.selected),'mobile-context',state.mobileContext?'active':'')}</nav><main class="workbench ${state.mobileContext?'mobile-context':'mobile-list'}"><section class="canvas">${deckCanvas()}</section>${assistant()}</main>`}
function diff(){return `<table class="delta-table"><thead><tr><th>Carta</th><th>Principale ${version()}</th><th>Variante</th><th>Variazione</th></tr></thead><tbody><tr><td>Iono</td><td>${state.adopted?3:4}</td><td>3</td><td class="delta">${state.adopted?'0':'−1'}</td></tr><tr><td>Mega Absol ex</td><td>${state.adopted?4:3}</td><td>4</td><td class="delta">${state.adopted?'0':'+1'}</td></tr></tbody></table>`}
function reasoning(){return `<div class="tradeoffs"><div><span class="eyebrow">Ipotesi da valutare</span><h3>Più copie di Absol</h3><p>La variante aumenta da tre a quattro le copie. Non dimostra un miglioramento del matchup.</p></div><div><span class="eyebrow">Compromesso</span><h3>Una Iono in meno</h3><p>La decisione riguarda entrambe le variazioni e tutte le 60 carte della lista.</p></div></div>`}
function conversation(){return `<details class="conversation"><summary>Discussione e motivazioni · 2 messaggi</summary><div class="message"><b>Tu</b><p>Vorrei valutare la quarta copia di Absol, togliendo una Iono.</p></div><div class="message"><b>Assistente · esempio</b><p>Confrontiamo la lista completa. L’effetto dell’intervento resta un’ipotesi; le fonti disponibili non forniscono un winrate per questa variante.</p></div><label for="followup">Continua la valutazione</label><textarea id="followup" placeholder="Quale compromesso vuoi approfondire?">${esc(state.message)}</textarea>${btn('Invia nel percorso','send-discussion','primary')}${btn('Dati e fonti','evidence','plain')}</details>`}
function decisionContent(){return `<div class="row between"><span class="eyebrow">Variante 01 / in valutazione</span><span class="tag purple">Base v3 → principale ${version()}</span></div><h1>Più disponibilità di Absol</h1><p class="muted">Una decisione sulla lista completa. Obiettivo, cambi e compromessi restano leggibili insieme.</p>${state.stale?`<div class="note warning"><b>La principale è cambiata: questa variante parte da v2.</b><p>L’adozione è bloccata. Continua su v3 per ottenere una nuova proposta e nuovi controlli.</p>${btn('Continua sulla principale attuale','rebase')}</div>`:state.adopted?`<div class="note"><b>Adottata come principale v4</b><p>La guida Hydrapple su v3 è ora storica. Puoi leggerla o avviare un aggiornamento.</p>${btn('Rivedi la preparazione','prepare')}</div>`:''}${reasoning()}<div class="row between"><h2>Cosa cambia</h2>${btn('Lista completa · 60','full-candidate','plain')}</div>${diff()}<div class="note warning"><b>2 verifiche aperte</b><p>Identità e ammissione di due stampe non confermate nella fixture. Nessun esito di legalità torneo.</p>${btn('Esamina i controlli','checks','plain')}</div><div class="row" style="margin-top:18px">${btn('Dati e fonti della proposta','evidence','plain')}${btn('Impatto sulla preparazione','impact','plain')}</div><div class="decision-footer"><span class="small muted">La lista principale cambia solo con la conferma.</span>${btn(state.adopted?'Variante adottata':'Valuta adozione','adopt','primary',state.stale||state.adopted?'disabled':'')}</div>${conversation()}`}
function decisions(){return `<div class="decision-shell"><aside class="rail">${title()}<p class="muted small">Mega Absol / Audino<br>Standard occidentale</p>${navigation()}${btn('Risorse','resources','plain')}</aside><aside class="idea-list"><h2>Percorsi del mazzo</h2><button class="idea active" data-action="candidate"><b>Più disponibilità di Absol</b><span>Da decidere · 2 variazioni</span></button><button class="idea" data-action="old"><b>Variante precedente</b><span>Base v2 · da riallineare</span></button>${btn('+ Esplora un’idea','new','primary')}<p class="small muted">Ogni percorso conserva la propria conversazione e le sue proposte.</p></aside><main class="decision-main">${state.page==='new'?newIdea():decisionContent()}</main></div>`}
function newIdea(){return `<span class="eyebrow">Nuovo percorso / principale ${version()}</span><h1>Cosa vuoi migliorare?</h1><p class="muted">Parti dalla domanda. Il percorso verrà creato con questa lista come base.</p><label for="ask">Domanda all’assistente</label><textarea id="ask" placeholder="Vorrei valutare una quarta copia di Absol">${esc(state.message)}</textarea><div class="row" style="margin-top:15px">${btn('Esplora l’idea','ask','primary')}${btn('Dati inviati e preferenze AI','evidence','plain')}</div>`}
const phaseCopy=[['Prepara una seconda linea','Prima di impegnare tutte le risorse sull’attaccante attivo, considera come proseguire se viene messo KO. Valuta la quarta copia di Absol rispetto alle alternative che vuoi mantenere in mano.','Quali risorse vuoi preservare per il turno successivo?'],['Valuta il compromesso di Iono','La variante riduce Iono da quattro a tre copie. Prima di adottarla, considera in quali situazioni avresti voluto quella copia e se la quarta copia di Absol risponde allo stesso problema.','La quarta copia di Absol serve al piano che stai valutando?'],['Mantieni aperta una seconda possibilità','Costruisci il turno finale considerando anche una mano diversa da quella attesa. La disponibilità di una carta nella lista non garantisce di averla nel momento decisivo.','Quale assunzione vuoi approfondire prima di adottare la variante?']];
function preparation(){const copy=phaseCopy[state.phase];const missing=state.opponent==='Gardevoir ex';return `${appbar()}<div class="versionstrip"><span>Preparazione legata alla principale <b>${version()}</b> · dati illustrativi</span>${btn('Apri lista · 60 carte','full-main','plain')}</div><main class="prepare-shell"><div class="preparation-title"><span class="eyebrow">Prima di giocare</span><h1>Quale matchup vuoi preparare?</h1><p class="muted">Scegli una guida, approfondisci il piano e valuta le modifiche nel suo contesto.</p></div><div class="prep-layout"><aside class="opponents" aria-label="Avversari"><p class="small muted">Archetipi dal metagame · esempio</p>${[['Hydrapple ex',state.adopted?'Storica · lista v3':'Disponibile · lista v3'],['Dragapult ex','Storica · lista v2'],['Gardevoir ex','Guida da generare']].map(([name,status])=>`<button class="opponent ${state.opponent===name?'active':''}" data-action="opponent" data-name="${name}"><b>${name}</b><span class="small">${status}</span></button>`).join('')}${btn('Periodo e fonti','meta','plain')}</aside><article class="guide"><header class="guide-header"><div class="row between"><span class="eyebrow">Mega Absol / Audino contro</span><span class="tag ${state.adopted||state.opponent==='Dragapult ex'?'amber':''}">${missing?'Da preparare':state.adopted||state.opponent==='Dragapult ex'?'Guida storica':'Guida su v3'}</span></div><h1>${esc(state.opponent)}</h1><div class="row">${btn('Fonti e limiti','evidence','plain')}${btn('Revisioni','revisions','plain')}</div></header>${missing?`<div class="empty"><h2>Costruisci il primo piano</h2><p>Usa la principale ${version()}, l’archetipo e le evidenze disponibili. Puoi controllare i dati prima di inviarli.</p>${btn('Vedi dati e genera guida','generate','primary')}</div>`:`<div class="guide-body">${state.adopted||state.opponent==='Dragapult ex'?`<div class="note warning"><b>Questa guida riguarda una lista precedente.</b><p>Resta consultabile. Un aggiornamento crea una nuova guida sulla principale ${version()}.</p>${btn('Prepara aggiornamento','generate')}</div>`:''}<nav class="phase-nav" aria-label="Momenti del piano">${['Apertura','Sviluppo','Chiusura'].map((label,i)=>btn(label,'phase',state.phase===i?'active':'',`data-value="${i}" aria-pressed="${state.phase===i}"`)).join('')}</nav><div class="guide-columns"><section class="reading"><div class="phase-number" aria-hidden="true">0${state.phase+1}</div><h2>${copy[0]}</h2><p>${copy[1]}</p><div class="note"><b>Domanda da approfondire</b><p>${copy[2]}</p></div><p class="micro">Testo illustrativo del percorso, senza valutazione competitiva verificata.</p></section><aside class="relevant"><h3>Carte nel contesto</h3>${['Iono','Mega Absol ex'].map(name=>`<button data-action="relevant-card" data-name="${name}"><b>${name}</b><small>${quantity(name)} copie · nella tua lista</small></button>`).join('')}<p class="small muted">La selezione apre la scheda senza abbandonare la guida.</p>${btn('Valuta Iono 4 → 3 / Absol 3 → 4','compare','primary')}</aside></div></div><div class="guide-question"><label for="guide-question"><b>Approfondisci questo punto</b></label><div class="row" style="margin-top:10px"><input id="guide-question" placeholder="Scrivi una domanda sul piano" value="${esc(state.message)}">${btn('Discuti il piano','guide-ask','primary')}</div>${state.response?'<div class="note" style="margin-top:14px"><b>Discussione aperta su questa guida</b><p>La tua domanda è collegata a questa fase, alla guida e alla versione del mazzo. Risposta dimostrativa; nessuna analisi AI eseguita.</p></div>':''}</div>`}</article></div></main>`}
function fullDeckPage(){return `${appbar()}<main class="full-deck"><div class="row between"><h1>Il tuo mazzo</h1>${current()}</div><div class="row">${btn('Esplora una variante','new','primary')}${btn('Controlli · 2','checks')}${btn('Versioni','history')}${btn('Copia lista','export')}</div>${rows()}</main>`}
function render(){let content;if(state.page==='prepare'||(state.concept==='c'&&state.page==='home'))content=preparation();else if(state.page==='deck')content=state.concept==='a'?workbench():fullDeckPage();else if(state.page==='decisions'||state.page==='new'||state.concept==='b')content=decisions();else content=workbench();$('#app').innerHTML=toolbar()+(state.result?`<div class="notice-result" role="status">${esc(state.result)}</div>`:'')+content+'<footer class="legend-fixture">Studio UX · dati e risposte dimostrativi · nessun salvataggio, invio AI o risultato competitivo. Riparti con “Ricomincia”.</footer>';document.body.classList.toggle('capture',params.has('capture'));const u=new URL(location.href);u.searchParams.set('concept',state.concept);history.replaceState(null,'',u);}
function modal(title,body,actions=''){const d=$('#detail');d.innerHTML=`${btn('Chiudi','close','plain close')}<h2>${title}</h2>${body}${actions?`<div class="dialog-actions">${actions}</div>`:''}`;if(!d.open)d.showModal();}
function checks(){modal('Controlli della variante',`<div class="note warning"><b>Due dati da verificare</b><p>Stampa di Ralts non identificata e data di ammissione di una stampa non coperta nella fixture.</p></div><h3 style="margin-top:24px">Costruzione</h3><p>60 carte · quantità consentite · vincolo “almeno 3 Absol” rispettato nella fixture.</p><p>Un dubbio sulla copertura non equivale a un divieto certo. Un errore certo bloccherebbe l’adozione.</p><p class="small muted">Controlli illustrativi, nessuna attestazione di legalità.</p>`)}
const actions={
 concept(el){state.concept=el.dataset.value;state.page='home';state.result='';render()},
 reset(){Object.assign(state,{page:'home',selected:'Iono',candidate:false,adopted:false,stale:false,phase:0,opponent:'Hydrapple ex',message:'',result:'',response:false,mobileContext:false});render()},
 deck(){state.page='deck';render()},decisions(){state.page='decisions';render()},prepare(){state.page='prepare';render()},
 card(el){state.selected=el.dataset.name;state.mobileContext=true;render();if(innerWidth<=800)window.scrollTo(0,0)},
 'mobile-list'(){state.mobileContext=false;render()},'mobile-context'(){state.mobileContext=true;render()},
 'card-detail'(){modal(state.selected,`<p>${quantity(state.selected)} copie nella principale ${version()}.</p><h3>Vincoli</h3><p>${state.selected==='Mega Absol ex'?'Almeno 3 copie. La variante ne contiene 4.':'Nessun vincolo obbligatorio su questa carta.'}</p><p class="muted">Qui restano stampe, testo e vincoli, collegati alla stessa identità di gioco.</p>`,btn('Discuti questa carta','close','primary'))},
 'relevant-card'(el){state.selected=el.dataset.name;actions['card-detail']()},
 ask(){state.message=$('#ask')?.value.trim()||'';if(!state.message){$('#ask').focus();return}state.candidate=true;state.result='Richiesta simulata: percorso creato e variante di esempio pronta.';if(state.concept!=='a')state.page='decisions';render()},
 candidate(){state.candidate=true;state.stale=false;state.page=state.concept==='a'?'home':'decisions';render()},
 old(){state.stale=true;state.page='decisions';render()},
 new(){state.page='new';state.message='';render()},
 compare(){modal('Valuta la variante completa',`<div class="row">${current()}<span class="tag purple">Variante · 60 carte · base v3</span></div>${reasoning()}${diff()}<div class="row">${btn('Controlli · 2 aperti','checks')}${btn('Lista completa','full-candidate')}${btn('Fonti','evidence')}</div><p class="small muted">La scelta comprende tutta la lista. Nessuna carta viene adottata singolarmente.</p>`,btn('Torna al lavoro','close')+btn(state.adopted?'Già adottata':'Valuta adozione','adopt','primary',state.adopted?'disabled':''))},
 adopt(){if(state.stale||state.adopted)return;modal('Adottare tutte le 60 carte?',`<p><b>La principale passerà da v3 a v4.</b> Iono: 4 → 3. Mega Absol ex: 3 → 4. Le altre quantità restano uguali.</p><div class="note warning"><b>Due verifiche aperte</b><p>Identità e ammissione di due stampe restano da controllare.</p></div><p>La guida Hydrapple su v3 sarà indicata come storica. Le conversazioni sulla vecchia base restano separate. Puoi ritrovare v3 nello storico.</p><p class="small muted">In questo prototipo la conferma cambia soltanto lo stato dimostrativo della pagina.</p>`,btn('Continua a valutare','compare')+btn('Conferma lista completa','confirm','primary'))},
 confirm(){state.adopted=true;state.result='Dimostrazione: principale v4. La guida su v3 è ora storica.';$('#detail').close();render()},
 rebase(){modal('Continua sulla principale v3',`<p>La variante su v2 resta nello storico. Un nuovo percorso userà la principale v3 e la vecchia proposta come contesto, con nuovi controlli prima dell’adozione.</p>`,btn('Apri nuovo percorso','new-current','primary'))},
 'new-current'(){state.stale=false;state.page='new';state.message='Rivaluta la proposta precedente sulla principale v3.';$('#detail').close();render()},
 'full-main'(){modal('Lista principale '+version(),rows())},'full-candidate'(){modal('Variante completa · 60 carte',rows(true),btn('Torna al confronto','compare'))},
 checks,
 evidence(){modal('Dati, fonti e limiti',`<p><b>Lista:</b> principale ${version()}, quantità, identità e vincoli.</p><p><b>Contesto:</b> carta o guida selezionata e conversazione di questo percorso.</p><p><b>Evidenze disponibili:</b> schede locali e liste torneo pertinenti. Provenienza, copertura e data accompagnano ogni risultato.</p><div class="note warning"><b>Fixture dello studio</b><p>Non sono state consultate fonti torneo per generare questi contenuti e non verrà inviata alcuna richiesta AI.</p></div><details style="margin-top:20px"><summary>Preferenze e dettagli tecnici</summary><p>Preferenze globali ereditate; nella UI reale qui si possono cambiare per il percorso e ispezionare le query.</p></details>`)},
 history(){modal('Versioni della principale',`<div class="stack">${state.adopted?'<div><b>v4 · principale</b><p>Adottata dalla variante “Più disponibilità di Absol”.</p></div>':''}<div><b>v3 ${state.adopted?'· precedente':'· principale'}</b><p>Iono ×4, Absol ×3. Origine della guida Hydrapple.</p></div><div><b>v2 · precedente</b><p>Origine del percorso storico. Nessun aggiornamento automatico delle sue proposte.</p></div></div>`)},
 impact(){modal('Cosa accade dopo l’adozione',`<p>La nuova principale diventa v4. Le guide basate su v3 vengono indicate come storiche e restano leggibili.</p><p>Puoi scegliere quali aggiornare; la generazione non parte automaticamente. Le altre conversazioni mantengono la propria base.</p>`)},
 phase(el){state.phase=Number(el.dataset.value);render()},opponent(el){state.opponent=el.dataset.name;state.phase=0;state.response=false;render()},
 'guide-ask'(){state.message=$('#guide-question').value.trim();if(!state.message){$('#guide-question').focus();return}state.response=true;render()},
 generate(){modal('Prepara una guida sulla principale '+version(),`<p>Avversario: <b>${esc(state.opponent)}</b>.</p><p>Lista e vincoli attuali, metagame selezionato e schede disponibili. L’analisi crea una nuova guida senza riscrivere quella storica.</p><div class="note"><b>Anteprima dimostrativa</b><p>Questo percorso mostra la scelta dei dati; il prototipo non genera guide reali.</p></div>`,btn('Esamina dati e limiti','evidence','primary'))},
 revisions(){modal('Revisioni della guida',`<p><b>Guida su v3</b> · discussione originale conservata.</p><p><b>Guida su v2</b> · storico, non corrente.</p><p>La revisione resta legata alla sua lista e alle fonti del momento.</p>`)},
 meta(){modal('Periodo e fonti del metagame',`<p>Standard occidentale · periodo e snapshot espliciti nella UI reale.</p><p>Gli avversari arrivano dall’indice metagame. “Guida disponibile” descrive la preparazione nell’app, non una probabilità di vittoria.</p>`)},
 discussion(){modal('Discuti la variante',conversation())},
 'send-discussion'(){const text=$('#followup')?.value.trim();if(!text){$('#followup')?.focus();return}state.result='Osservazione dimostrativa conservata nel percorso della variante.';state.message=text;if($('#detail').open)$('#detail').close();render()},
 export(){modal('Copia della lista',`<p>Nell’app il comando copia immediatamente la principale. Qui non viene scritto negli appunti un mazzo illustrativo.</p><p>La posizione del comando resta vicina alla versione su cui stai lavorando.</p>`)},
 resources(){modal('Risorse condivise',`<div class="stack"><div><h3>Catalogo</h3><p>Ricerca e aggiornamento globale delle carte. Le schede utili si aprono anche dal mazzo o dal piano.</p></div><div><h3>Eventi e fonti</h3><p>Acquisizioni e copertura condivise fra progetti.</p></div><div><h3>Preferenze AI</h3><p>Connessione e impostazioni globali, con eventuali scelte per singolo percorso.</p></div></div>`)},
 analysis(){modal('Quale lavoro deve guidare l’app?',`<p><b>A · Banco del mazzo.</b> Parte dalle carte. La domanda crea il percorso; l’assistente occupa il contesto. Adatto all’iterazione frequente sulla lista.</p><p><b>B · Decisioni.</b> Parte dalle varianti. Il confronto ha uno spazio proprio e la conversazione resta collegata. Adatto a più ipotesi parallele; richiede un ingresso semplice per chi non ha ancora proposte.</p><p><b>C · Preparazione.</b> Parte dagli avversari. Piano e carte pertinenti guidano il lavoro; lista completa e fonti si aprono quando servono. Utile prima di giocare; meno diretto per costruire il mazzo.</p><p><b>Proposta:</b> A come spazio principale, valutazione B quando arriva una variante, preparazione C come attività distinta. Un solo modello di versioni e conversazioni.</p>`)},
 close(){$('#detail').close()}
};
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(el&&!el.disabled)actions[el.dataset.action]?.(el)});
document.addEventListener('input',event=>{if(['ask','followup','guide-question'].includes(event.target.id))state.message=event.target.value});
render();
